import sys
sys.path.insert(0, '.codex/skills/docx')

from scripts.document import Document

target = sys.argv[1] if len(sys.argv) > 1 else 'unpacked'
doc = Document(target)
editor = doc['word/document.xml']

for para in editor.dom.getElementsByTagName('w:p'):
    text = ''.join(t.firstChild.nodeValue or '' for t in para.getElementsByTagName('w:t') if t.firstChild).strip()
    if not text:
        continue
    underlined = False
    for run in para.getElementsByTagName('w:r'):
        for u in run.getElementsByTagName('w:u'):
            if u.getAttribute('w:val') == 'single':
                underlined = True
    print('%s | underlined=%s' % (text, underlined))
